import 'dart:convert';

import 'package:flutter/services.dart';

const seedFiles = ['academic', 'timetables', 'calendar', 'announcements', 'exams', 'campus', 'electives', 'imports'];

/// Loads the bundled reference data generated by tools/build_seed.py.
Future<Map<String, dynamic>> loadBundledSeed([AssetBundle? bundle]) async {
  final b = bundle ?? rootBundle;
  final out = <String, dynamic>{};
  for (final f in seedFiles) {
    out[f] = jsonDecode(await b.loadString('assets/seed/$f.json'));
  }
  return out;
}
